// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;

    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 0, 1 ether);

        Reverter rev = new Reverter();

        vm.deal(address(c), 1 ether);

        address owner = address(this);
        vm.prank(owner);

        bool ok;
        try c.sendMoney(address(rev), amount) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(!ok);
    }
}

contract Reverter {
    fallback() external payable {
        revert("revert in fallback");
    }

    receive() external payable {
        revert("revert in receive");
    }
}
